class Solution {
    struct Node {
        string name;
        map<string, Node*> children;
        string serial;
        bool deleted = false;
        Node(string n = "") : name(n) {}
    };
    unordered_map<string, int> serialCounts;

    string serialize(Node* node) {
        if (node->children.empty()) return "";
        string s = "";
        for (auto& [name, child] : node->children) {
            string sub = serialize(child);
            s += name + "(" + sub + ")";
        }
        node->serial = s;
        serialCounts[s]++;
        return s;
    }

    void mark(Node* node) {
        if (!node->serial.empty() && serialCounts[node->serial] > 1) {
            node->deleted = true;
            return;
        }
        for (auto& [_, child] : node->children) mark(child);
    }

    void collect(Node* node, vector<string>& curr, vector<vector<string>>& ans) {
        for (auto& [name, child] : node->children) {
            if (!child->deleted) {
                curr.push_back(name);
                ans.push_back(curr);
                collect(child, curr, ans);
                curr.pop_back();
            }
        }
    }

public:
    vector<vector<string>> deleteDuplicateFolder(vector<vector<string>>& paths) {
        Node* root = new Node();
        for (auto& p : paths) {
            Node* curr = root;
            for (const string& folder : p) {
                if (!curr->children.count(folder)) curr->children[folder] = new Node(folder);
                curr = curr->children[folder];
            }
        }
        serialize(root);
        mark(root);
        vector<vector<string>> ans;
        vector<string> curr;
        collect(root, curr, ans);
        return ans;
    }
};

class Solution {
    static class Node {
        String name;
        java.util.TreeMap<String, Node> children = new java.util.TreeMap<>();
        String serial = "";
        boolean deleted = false;
        Node(String n) { this.name = n; }
    }

    private java.util.Map<String, Integer> serialCounts = new java.util.HashMap<>();

    private String serialize(Node node) {
        if (node.children.isEmpty()) return "";
        StringBuilder sb = new StringBuilder();
        for (java.util.Map.Entry<String, Node> entry : node.children.entrySet()) {
            String sub = serialize(entry.getValue());
            sb.append(entry.getKey()).append("(").append(sub).append(")");
        }
        node.serial = sb.toString();
        serialCounts.put(node.serial, serialCounts.getOrDefault(node.serial, 0) + 1);
        return node.serial;
    }

    private void mark(Node node) {
        if (!node.serial.isEmpty() && serialCounts.getOrDefault(node.serial, 0) > 1) {
            node.deleted = true;
            return;
        }
        for (Node child : node.children.values()) mark(child);
    }

    private void collect(Node node, java.util.List<String> curr, java.util.List<java.util.List<String>> ans) {
        for (java.util.Map.Entry<String, Node> entry : node.children.entrySet()) {
            Node child = entry.getValue();
            if (!child.deleted) {
                curr.add(entry.getKey());
                ans.add(new java.util.ArrayList<>(curr));
                collect(child, curr, ans);
                curr.remove(curr.size() - 1);
            }
        }
    }

    public java.util.List<java.util.List<String>> deleteDuplicateFolder(java.util.List<java.util.List<String>> paths) {
        Node root = new Node("");
        for (java.util.List<String> p : paths) {
            Node curr = root;
            for (String folder : p) {
                curr.children.putIfAbsent(folder, new Node(folder));
                curr = curr.children.get(folder);
            }
        }
        serialize(root);
        mark(root);
        java.util.List<java.util.List<String>> ans = new java.util.ArrayList<>();
        collect(root, new java.util.ArrayList<>(), ans);
        return ans;
    }
}

var deleteDuplicateFolder = function(paths) {
  class Node {
    constructor(name = '') {
      this.name = name;
      this.children = new Map();
      this.serial = '';
      this.deleted = false;
    }
  }

  const root = new Node();
  for (const p of paths) {
    let curr = root;
    for (const folder of p) {
      if (!curr.children.has(folder)) curr.children.set(folder, new Node(folder));
      curr = curr.children.get(folder);
    }
  }

  const serialCounts = new Map();
  const serialize = (node) => {
    if (node.children.size === 0) return '';
    const sortedKeys = Array.from(node.children.keys()).sort();
    const parts = [];
    for (const k of sortedKeys) {
      const sub = serialize(node.children.get(k));
      parts.push(`${k}(${sub})`);
    }
    node.serial = parts.join('');
    serialCounts.set(node.serial, (serialCounts.get(node.serial) || 0) + 1);
    return node.serial;
  };

  serialize(root);

  const mark = (node) => {
    if (node.serial && (serialCounts.get(node.serial) || 0) > 1) {
      node.deleted = true;
      return;
    }
    for (const child of node.children.values()) mark(child);
  };

  mark(root);

  const ans = [];
  const collect = (node, curr) => {
    const sortedKeys = Array.from(node.children.keys()).sort();
    for (const k of sortedKeys) {
      const child = node.children.get(k);
      if (!child.deleted) {
        ans.push([...curr, k]);
        collect(child, [...curr, k]);
      }
    }
  };

  collect(root, []);
  return ans;
};
